import{modes,fresh,round,assess,maze,episode,rng}from'./lab2.js';
const $=id=>document.getElementById(id),names={fixed:'Fixed',rl:'RL',random:'随机调参',rsi:'RSI 模拟'},colors=['#999','#6593c0','#be9445','#277656'];let agents={},n=0,done=false,busy=false;
function render(){ $('stats').innerHTML=modes.map(m=>{let a=agents[m];return `<tr><th>${names[m]}</th><td>${a.spent}</td><td>${a.train}</td><td>${a.validation}</td><td>${a.history.length?a.history.at(-1).toFixed(1)+'%':'—'}</td><td>${a.accepted}</td></tr>`}).join('');$('journal').innerHTML=['rsi','random'].map(m=>`<h3>${names[m]}</h3>`+agents[m].logs.slice(-5).map(x=>`<p>${x}</p>`).join('')).join('');$('plot').innerHTML=[0,50,100].map(x=>`<text x="0" y="${155-x*1.3}" font-size="10">${x}%</text><path d="M35 ${150-x*1.3}H690" stroke="#ddd"/>`).join('')+modes.map((m,k)=>`<polyline fill="none" stroke="${colors[k]}" stroke-width="2" points="${agents[m].history.map((v,i)=>`${35+(i+1)*65},${150-v*1.3}`).join(' ')}"/><text x="${40+k*160}" y="178" fill="${colors[k]}">${names[m]}</text>`).join('');replay()}
function replay(){const m=$('agent').value,w=maze(900001),out=episode(agents[m],w,rng(1),false,120,m==='fixed'),p=out.path.at(-1);$('board').innerHTML=w.map((wall,i)=>{let visible=Math.abs(i%10-p%10)<=2&&Math.abs((i/10|0)-(p/10|0))<=2;return `<div class="cell ${wall?'wall':''} ${out.path.includes(i)?'visited':''} ${i===99?'goal':''} ${i===p?'bot':''}" style="opacity:${visible?1:.3}">${i===p?'▣':i===99?'⚑':''}</div>`}).join('');$('replay').textContent=`${names[m]} 演示轨迹：${out.success?'抵达':'未抵达'}，${out.steps} 步，重复访问 ${out.repeats} 次。`}
function reset(){n=0;done=false;agents=Object.fromEntries(modes.map(m=>[m,fresh()]));$('run').disabled=false;$('finish').disabled=false;$('seed').disabled=false;$('results').textContent='测试封存中';render()}
$('run').onclick=async()=>{if(done||busy)return;busy=true;$('run').disabled=true;$('seed').disabled=true;$('finish').disabled=true;$('reset').disabled=true;await new Promise(r=>setTimeout(r,20));for(const m of modes)round(agents[m],m,Number($('seed').value)*100000+n*1000);n++;render();$('status').textContent=`已完成 ${n} / 10 轮；每组额度 ${n*6440}。`;busy=false;$('run').disabled=n>=10;$('finish').disabled=false;$('reset').disabled=false};
$('finish').onclick=()=>{done=true;$('run').disabled=true;$('finish').disabled=true;$('results').innerHTML=modes.map(m=>{let a=assess(agents[m],800000,40,false,m==='fixed'),b=assess(agents[m],850000,40,true,m==='fixed');return `<p><b>${names[m]}</b>：同类 ${a.rate.toFixed(1)}%，绕路 ${b.rate.toFixed(1)}%；测试额外行动 ${a.used+b.used}；成功平均步数 ${a.avg?.toFixed(1)??'—'} / ${b.avg?.toFixed(1)??'—'}。</p>`}).join('');$('status').textContent='实验已封存。重新开始可选择另一个种子重复实验。'};$('reset').onclick=reset;$('seed').onchange=reset;$('agent').onchange=replay;reset();
